Q: Stripe elements separate fields A: <p>Use this is your html</p>
<pre><code>  &lt;div class=&quot;row&quot;&gt;
        &lt;!-- 1. Card Number Field --&gt;
        &lt;div class=&quot;col-md-6 form-group mb-3&quot;&gt;
            &lt;label&gt;Card Number&lt;/label&gt;
            &lt;!-- Stripe injects iframe here --&gt;
            &lt;div id=&quot;card-number&quot; class=&quot;stripe-element&quot;&gt;&lt;/div&gt;
        &lt;/div&gt;
    &lt;/div&gt;
    &lt;div class=&quot;row&quot;&gt;
        &lt;!-- 2. Expiry Field --&gt;
        &lt;div class=&quot;col-md-6 form-group mb-3&quot;&gt;
            &lt;label&gt;Expiry Date&lt;/label&gt;
            &lt;div id=&quot;card-expiry&quot; class=&quot;stripe-element&quot;&gt;&lt;/div&gt;
        &lt;/div&gt;
        &lt;!-- 3. CVC Field --&gt;
        &lt;div class=&quot;col-md-6 form-group mb-3&quot;&gt;
            &lt;label&gt;CVC&lt;/label&gt;
            &lt;div id=&quot;card-cvc&quot; class=&quot;stripe-element&quot;&gt;&lt;/div&gt;
        &lt;/div&gt;
    &lt;/div&gt;
</code></pre>
<p>And then this in your js</p>
<pre><code>cardNumberElement = elements.create('cardNumber', {  placeholder: '0000 0000 0000 0000' });
cardExpiryElement = elements.create('cardExpiry', {  placeholder: 'MM / YY' });
cardCvcElement = elements.create('cardCvc', { , placeholder: '123' });             cardNumberElement.mount('#card-number');
cardExpiryElement.mount('#card-expiry');
cardCvcElement.mount('#card-cvc');
</code></pre>

Q: Can I iterate over/get an iterable over multiple promises by order of their settlement? A: <p>Here's a  function that maps input promises onto a new array of promises, each with its own  captured resolver.  As each input promise settles, it finds the first non-null resolver, calls it, and then nulls it.</p>
<p>To loop in settlement order, loop the new array, awaiting each. If you want a generator, move the caller's the loop into the function and yield each value. You can handle rejections by resolving to something like <code>{ status, value / reason }</code> instead of just the value.</p>
<pre><code>
function inSettlementOrder(promises) {
    const slots = [];
    const resolvers = [];

    for (let i = 0; i &lt; promises.length; i++) {
        slots[i] = new Promise(r =&gt; resolvers[i] = r);
    }

/*
    for (const p of promises) {
        Promise.resolve(p).then(value =&gt; {
            const i = resolvers.findIndex(r =&gt; r !== null);
            resolvers[i](value);
            resolvers[i] = null;
        });
    }
 */

    // OP's idea to capture next index and avoid the find...
    let next = 0;
    for (const p of promises) {
        Promise.resolve(p).then(value =&gt; {
            resolvers[next](value);
            resolvers[next] = null;
            next++;
        });
    }

    return slots;
}

async function test() {
    const promises = [
        new Promise(r =&gt; setTimeout(() =&gt; r(&quot;3 seconds&quot;), 3000)),
        new Promise(r =&gt; setTimeout(() =&gt; r(&quot;1 second&quot;), 1000)),
        new Promise(r =&gt; setTimeout(() =&gt; r(&quot;2 seconds&quot;), 2000)),
    ];

    const slots = inSettlementOrder(promises);

    for (let i = 0; i &lt; slots.length; i++) {
        const value = await slots[i];
        console.log(value);
    }
}

test();
</code></pre>
